package com.xmission.trevin.android.tangram.data;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;

import com.xmission.trevin.android.tangram.data.TangramPreferences.Corner;
import com.xmission.trevin.android.tangram.ui.PlayTableView;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;

/**
 * Maintains the assignment of the movable play-field controls (Exit,
 * Goal, and Save) to the four corners of the {@link PlayTableView},
 * leaving one corner empty.  This is the pure model behind the
 * Preferences drag-and-drop corner layout: it resolves any collisions
 * in the initial preferences and swaps controls when one is moved into
 * a corner already occupied by another.
 *
 * <p>There are always exactly four corners and four &ldquo;controls&rdquo;
 * &mdash; {@link Control#EXIT}, {@link Control#GOAL}, {@link Control#SAVE},
 * and {@link Control#NONE} (the empty corner) &mdash; so the mapping is a
 * bijection.</p>
 *
 * @author Claude Opus 4.8
 */
public class CornerButtonModel {

    /** A control that can occupy a corner; {@link #NONE} marks the empty one. */
    public enum Control { NONE, EXIT, GOAL, SAVE }

    /** Priority order for resolving collisions when initializing. */
    private static final Control[] PRIORITY =
            { Control.EXIT, Control.GOAL, Control.SAVE };

    private final EnumMap<Corner, Control> byCorner = new EnumMap<>(Corner.class);
    private final EnumMap<Control, Corner> byControl = new EnumMap<>(Control.class);

    /**
     * Build the model from the (possibly colliding) preferred corners.
     * Requests are honored in priority order (Exit, then Goal, then Save);
     * any control whose preferred corner is already taken is placed in the
     * first remaining free corner, and the last free corner is left empty.
     *
     * @param exit the preferred corner for the Exit control
     * @param goal the preferred corner for the Goal control
     * @param save the preferred corner for the Save control
     */
    public CornerButtonModel(@NonNull Corner exit, @NonNull Corner goal,
                             @NonNull Corner save) {
        EnumMap<Control, Corner> requested = new EnumMap<>(Control.class);
        requested.put(Control.EXIT, exit);
        requested.put(Control.GOAL, goal);
        requested.put(Control.SAVE, save);

        // First pass: honor non-colliding requests in priority order.
        List<Control> deferred = new ArrayList<>(PRIORITY.length);
        for (Control control : PRIORITY) {
            Corner want = requested.get(control);
            if (want != null && !byCorner.containsKey(want))
                assign(control, want);
            else
                deferred.add(control);
        }
        // Second pass: place any displaced controls in free corners.
        for (Control control : deferred)
            assign(control, firstFreeCorner());
        // Whatever corner is left over is the empty one.
        Corner empty = firstFreeCorner();
        if (empty != null)
            assign(Control.NONE, empty);
    }

    /** @return the first corner with no control assigned, or {@code null}. */
    @Nullable
    private Corner firstFreeCorner() {
        for (Corner corner : Corner.values()) {
            if (!byCorner.containsKey(corner))
                return corner;
        }
        return null;
    }

    /** Record a control in a corner, updating both directions of the map. */
    private void assign(@NonNull Control control, @NonNull Corner corner) {
        byCorner.put(corner, control);
        byControl.put(control, corner);
    }

    /**
     * @param control the control to locate
     * @return the corner currently holding the given control
     */
    public Corner cornerFor(@NonNull Control control) {
        return byControl.get(control);
    }

    /**
     * @param corner the corner to inspect
     * @return the control currently in the given corner
     */
    public Control controlAt(@NonNull Corner corner) {
        return byCorner.get(corner);
    }

    /**
     * Move a control into a corner.  Whatever was in the target corner
     * (which may be {@link Control#NONE}) is swapped into the corner the
     * moved control came from.
     *
     * @param control the control being moved; {@link Control#NONE} is ignored
     * @param target the corner to move it into
     * @return {@code true} if the assignment changed, {@code false} if the
     * control was already in the target corner (or the move was a no-op)
     */
    public boolean place(@NonNull Control control, @NonNull Corner target) {
        if (control == Control.NONE)
            return false;
        Corner source = byControl.get(control);
        if (source == target)
            return false;
        Control occupant = byCorner.get(target);
        assign(control, target);
        assign(occupant, source);
        return true;
    }

}